import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.BM_-pWjS.js";const m=JSON.parse('{"title":"Labeling","description":"","frontmatter":{},"headers":[],"relativePath":"en/labeling.md","filePath":"en/labeling.md"}'),o={name:"en/labeling.md"};function d(s,e,r,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="labeling" tabindex="-1">Labeling <a class="header-anchor" href="#labeling" aria-label="Permalink to &quot;Labeling&quot;">​</a></h1><h2 id="why-labeling-matters" tabindex="-1">Why labeling matters <a class="header-anchor" href="#why-labeling-matters" aria-label="Permalink to &quot;Why labeling matters&quot;">​</a></h2><p>Shooting RAW+JPG simultaneously means your folder ends up with a mix of camera JPEGs, RAW files, and developed exports all in one place — and file names alone give no indication of where each file stands in your workflow. To solve this, bridge-lite automatically analyzes every file when you open a folder, combining the file extension, EXIF Software tag, and stem name to determine its type, then displays the result as a badge on each thumbnail. At a glance, the thumbnail grid shows you exactly which files are straight-out-of-camera, which are RAW, and which have been developed, preventing missed files and accidental culling of the wrong variant.</p><h2 id="badge-types" tabindex="-1">Badge types <a class="header-anchor" href="#badge-types" aria-label="Permalink to &quot;Badge types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Badge</th><th>Meaning</th><th>How it&#39;s determined</th></tr></thead><tbody><tr><td><code>SOOC</code></td><td>Straight-out-of-camera JPEG</td><td>JPEG extension and EXIF Software tag does not match a known editing application</td></tr><tr><td><code>RAW</code></td><td>RAW file</td><td>File extension (<code>.arw</code>, <code>.cr3</code>, <code>.nef</code>, etc.)</td></tr><tr><td><code>Developed</code></td><td>Developed variant</td><td>EXIF Software tag contains a keyword from a known editor (Lightroom, Capture One, etc.)</td></tr><tr><td><code>Indeterminate</code></td><td>File type could not be determined</td><td>Does not match any of the above</td></tr></tbody></table><h2 id="cases-where-detection-may-fail" tabindex="-1">Cases where detection may fail <a class="header-anchor" href="#cases-where-detection-may-fail" aria-label="Permalink to &quot;Cases where detection may fail&quot;">​</a></h2><p>Automatic detection is heuristic-based. The following situations can lead to incorrect results.</p><p><strong>Files with no EXIF data</strong> Without EXIF data, the Software tag cannot be read. Files in this state may show as <code>Indeterminate</code> because developed status cannot be determined.</p><p><strong>Files with intentionally stripped EXIF</strong> When EXIF has been deliberately removed (e.g. before client delivery), grouping falls back to pHash (perceptual hash) visual similarity alone. This increases the risk of incorrectly grouping visually similar shots from different exposures.</p><p><strong>Files exported by an unrecognized application</strong> If the EXIF Software tag contains an application name not in bridge-lite&#39;s known list, the file will not be classified as <code>Developed</code> and may appear as <code>Indeterminate</code> or <code>SOOC</code> instead.</p><p><strong>Files from cameras with non-DCF naming</strong> Files that do not follow the standard DCF naming convention (e.g. <code>DSC00001</code>) used by major camera manufacturers are more prone to incorrect grouping with unrelated shots.</p><h2 id="duplicate-badge" tabindex="-1">Duplicate badge <a class="header-anchor" href="#duplicate-badge" aria-label="Permalink to &quot;Duplicate badge&quot;">​</a></h2><p>When two or more files with byte-for-byte identical content exist in the folder, a duplicate badge is shown. This is useful for catching accidental double-exports of the same developed result.</p><p>Detection works in two stages. First, only files that share the same file size are treated as candidates — files with unique sizes are immediately excluded. SHA-256 hashes are then computed for those candidates only, and files with matching hashes are marked as duplicates. Because the comparison is content-based, files with different names are still detected if their contents are identical. Hash values are cached, so subsequent scans are fast.</p>',14)])])}const f=t(o,[["render",d]]);export{m as __pageData,f as default};
